from flask import Flask, request, jsonify

app = Flask(__name__)

# Dictionary of product codes and their prices
PRODUCT_PRICES = {
    "P001": 10.99,
    "P002": 15.50,
    "P003": 7.25,
    "P004": 20.00
}

def get_price(product_code):
    """Returns the price for a given product code."""
    return PRODUCT_PRICES.get(product_code, None)

@app.route('/calculate', methods=['GET'])
def calculate_price():
    """Calculates the total price for a product code and quantity."""
    product_code = request.args.get('product_code')
    quantity = request.args.get('quantity', type=int)

    if not product_code:
        return jsonify({"error": "Product code is required"}), 400
    if not quantity or quantity <= 0:
        return jsonify({"error": "Quantity must be a positive integer"}), 400

    price = get_price(product_code)
    if price is None:
        return jsonify({"error": "Product code not found"}), 404

    total_price = price * quantity
    return jsonify({
        "product_code": product_code,
        "quantity": quantity,
        "unit_price": price,
        "total_price": total_price
    })

if __name__ == '__main__':
    app.run(port=5000)

